abhinav_10_11 = {
    'hi': '।।7.10--7.11।। श्री अभिनवगुप्त कहते हैं: हे पार्थ ! मुझे सर्व भूतों का सनातन बीज (नित्य कारण) जानो। मैं बुद्धिमानों की बुद्धि और तेजस्वियों का तेज हूँ। बलवानों का काम-राग-रहित बल और सर्व भूतों में धर्म से अविरुद्ध काम मैं ही हूँ।',
    'en': '7.10--7.11 Sri Abhinavagupta states: O Partha, know Me to be the eternal seed of all beings. I am the intellect of the intelligent and splendour of the resplendent. I am the strength of the strong devoid of lust and attachment, and in all beings, desire uncontrary to Dharma.',
    'be': '৭.১০--৭.১১ শ্রী অভিনবগুপ্ত বলেছেন: হে পার্থ! আমাকে সর্ব ভূতের সনাতন বীজ (নিত্য কারণ) জানো। আমি বুদ্ধিমানদের বুদ্ধি এবং তেজস্বীদের তেজ। বলবানদের কাম-রাগ-রহিত বল এবং সর্ব ভূতে ধর্ম থেকে অবিরুদ্ধ কাম আমিই।',
    'ka': '೭.೧೦--೭.೧೧ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಹೇ ಪಾರ್ಥ! ನನ್ನನ್ನು ಸರ್ವ ಭೂತಗಳ ಸನಾತನ ಬೀಜವೆಂದು (ನಿತ್ಯಕಾರಣ) ತಿಳಿಯಿ. ನಾನು ಬುದ್ಧಿವಂತರ ಬುದ್ಧಿ ಹಾಗೂ ತೇಜಸ್ವಿಗಳ ತೇಜಸ್ಸಾಗಿದ್ದೇನೆ. ಬಲವಂತರ ಕಾಮರಾಗರಹಿತ ಬಲವೂ ಸರ್ವ ಭೂತಗಳಲ್ಲಿ ಧರ್ಮಕ್ಕೆ ಅವಿರುದ್ಧವಾದ ಕಾಮವೂ ನಾನೇ ಆಗಿದ್ದೇನೆ'
}

abhinav_12_13 = {
    'hi': '।।7.12--7.13।। श्री अभिनवगुप्त कहते हैं: जो भी सात्त्विक, राजस और तामस भाव हैं, उन्हें मुझसे ही उत्पन्न हुए जानो। यद्यपि वे सब मुझमें अवस्थित हैं, तथापि मैं उनमें लिप्त नहीं हूँ (स्वतंत्र हूँ)। इन तीनों गुणमयी भावों से विमोहित यह सम्पूर्ण जगत् मुझ उनसे अतीत और अविनाशी परमेश्वर को नहीं पहचानता।',
    'en': '7.12--7.13 Sri Abhinavagupta states: Whatever states that are Sattvic, Rajasic, or Tamasic, know them to proceed from Me alone; I am not in them, but they are in Me. Deluded by these states composed of the three Gunas, this entire world fails to recognize Me, who am beyond them and imperishable.',
    'be': '৭.১২--৭.১৩ শ্রী অভিনবগুপ্ত বলেছেন: যেও সাত্ত্বিক, রাজস ও তামস ভাব আছে, তাদের আমা থেকেই উৎপন্ন হওয়া জানো। যদিও সে সব আমাতে অবস্থিত, তথাপি আমি তাদের মধ্যে লিপ্ত নই (স্বতন্ত্র)। এই তিন গুণময় ভাব থেকে বিমোহিত এই সম্পূর্ণ জগৎ আমা তাদের থেকে অতীত ও অবিনাশী পরমেশ্বরকে চেনে না।',
    'ka': '೭.೧೨--೭.೧೩ ಶ್ರೀ ಅಭಿನವಗುಪ್ತರು ಹೇಳುತ್ತಾರೆ: ಯಾವ ಸಾತ್ತ್ವಿಕ, ರಾಜಸ ಹಾಗೂ ತಾಮಸ ಭಾವಗಳಿವೆಯೋ, ಅವು ನನ್ನಿಂದಲೇ ಉತ್ಪನ್ನವಾದವುಗಳು ಎಂದು ತಿಳಿಯಿ. ಅವುಗಳೆಲ್ಲವೂ ನನ್ನಲ್ಲಿ ನೆಲೆಸಿದಾಗ್ಯೂ, ನಾನು ಅವುಗಳಲ್ಲಿ ಲಿಪ್ತನಾಗಿಲ್ಲ (ಸ್ವತಂತ್ರ). ಈ ಮೂರು ಗುಣಮಯ ಭಾವಗಳಿಂದ ವಿಮೋಹಿತಗೊಂಡ ಈ ಸಮಸ್ತ ಜಗತ್ತು ಅವುಗಳಿಗಿಂತಲೂ ಅತೀತನೂ ಅವಿನಾಶಿಯೂ ಆದ ಪರಮೇಶ್ವರನಾದ ನನ್ನನ್ನು ಗುರುತಿಸುವುದಿಲ್ಲ'
}

